#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <string>
#include <vector>
using namespace std;

static string expected(string remaining) {
    string result;
    for (size_t width = 1; width <= remaining.size(); ++width) {
        size_t pos = remaining.find(string(width, ' '));
        if (pos == string::npos) break;
        result += remaining.substr(0, pos) + '\n';
        remaining.erase(0, pos + width);
    }
    return result + remaining;
}

static string show(const string& s) {
    string result;
    for (char c : s) {
        if (c == '\n') result += "\\n";
        else if (c == ' ') result += "·";
        else result += c;
        if (result.size() > 125) { result += "..."; break; }
    }
    return result;
}

static bool check(const string& exe, const string& input, int id) {
    const string inFile = "l3p2_input.txt", outFile = "l3p2_output.txt";
    { ofstream out(inFile, ios::binary); out << input << '\n'; }
    const string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream out(outFile, ios::binary);
    string actual((istreambuf_iterator<char>(out)), istreambuf_iterator<char>());
    // Treat CRLF as a line separator; never strip meaningful leading/interior spaces or blank lines.
    for (size_t i = 0; i + 1 < actual.size(); ++i)
        if (actual[i] == '\r' && actual[i+1] == '\n') actual.erase(i, 1);
    if (!actual.empty() && actual.back() == '\n') actual.pop_back();
    string want = expected(input);
    bool ok = code == 0 && actual == want;
    if (!ok) cout << "[FAIL] case " << id << ": input=" << show(input)
                  << " expected=" << show(want) << " actual=" << show(actual)
                  << " process status=" << code << '\n';
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<string> tests = {
        "sdfd 55 55   99312", "AbCd   999", "", "hello", " abc", "  abc",
        "   abc", "a b", "a  b", "a   b", "a    b", "  1  2   3    4",
        "a b c", "a b  c", "a  b c", "a b   c", "a  b   c    d",
        "a    b     c", "  A   B", "XYZ012", "1 2  3   4",
        string(999, 'a'), string(999, ' ') + "Z", string(500, ' ') + "Q"
    };
    unsigned seed = 202609u;
    for (int trial = 0; trial < 12; ++trial) {
        string s;
        for (int i = 0; i < 100 + trial * 73 && i < 990; ++i) {
            seed = seed * 1664525u + 1013904223u;
            s += (seed % 5u == 0 ? ' ' : "aB9c"[seed % 4u]);
        }
        s += 'Z';
        tests.push_back(s);
    }
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i], static_cast<int>(i+1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}
